const sameStrongIdentitySignal=(left?:PrinterDeviceIdentity,right?:PrinterDeviceIdentity)=>{
  const keys=['machineId','uuid','serial','mcuSerial','macAddress'] as const;
  return keys.some(key=>{
    const a=left?.signals[key]?.trim().toLowerCase(),b=right?.signals[key]?.trim().toLowerCase();
