    ?{...existing,host:row.host,deviceIdentity:refreshDeviceIdentityEvidence(existing.deviceIdentity,row.deviceIdentity??row.detection?.deviceIdentity)}
    :{
      id:crypto.randomUUID(),name,host:row.host,icon:iconForPreset('custom'),profile:profileForPreset('custom'),
      deviceIdentity:row.deviceIdentity??row.detection?.deviceIdentity,
      modelSelection:{mode:'automatic',selectedPreset:'custom',source:'automatic',updatedAt:Date.now()},
