 return <div className="phonePin" role="group" aria-label="Цифровая клавиатура PIN-кода" tabIndex={0} onKeyDown={event=>{if(disabled)return;if(/^\d$/.test(event.key)){event.preventDefault();add(event.key)}else if(event.key==='Backspace'){event.preventDefault();onChange(value.slice(0,-1))}else if(event.key==='Delete'){event.preventDefault();onChange('')}}}>
  <output className="phonePinDisplay" aria-label={`Введено цифр: ${value.length} из ${PIN_LENGTH}`}>{Array.from({length:PIN_LENGTH},(_,index)=><i key={index} className={index<value.length?'filled':''}/>)}</output>
