export function LoginPreferences({user,onConfigure}:{user:AppUser;onConfigure:(mode:'password'|'pin')=>void}){
 const [method,setMethod]=useState<LoginMethod>(preferredLoginMethod),[hello,setHello]=useState<HelloStatus>(),[busy,setBusy]=useState(false),[message,setMessage]=useState('');
 useEffect(()=>{const changed=()=>setMethod(preferredLoginMethod());window.addEventListener('klipper-auth-method-changed',changed);return()=>window.removeEventListener('klipper-auth-method-changed',changed)},[]);
 useEffect(()=>{if(method!=='hello')return;let cancelled=false;setHello(undefined);setMessage('');helloStatus(user.id).then(value=>{if(!cancelled){setHello(value);if(value.enrolled)saveLoginMethod('hello')}}).catch(e=>{if(!cancelled)setMessage(String(e))});return()=>{cancelled=true}},[method,user.id]);
 const choose=(next:LoginMethod)=>{setMethod(next);setMessage('');if(next==='password'||next==='pin'&&user.pinEnabled||next==='hello'&&hello?.enrolled)saveLoginMethod(next)};
 const connect=async()=>{setBusy(true);setMessage('');try{await enableHello();const status=await helloStatus(user.id);setHello(status);if(!status.enrolled)throw new Error('Windows Hello не подключён. Повторите настройку.');saveLoginMethod('hello');setMessage('Windows Hello включён для вашего входа на этом ПК.')}catch(e){setMessage(String(e))}finally{setBusy(false)}};
 const disconnect=async()=>{setBusy(true);setMessage('');try{await disableHello();setHello(undefined);const fallback=user.pinEnabled?'pin':'password';setMethod(fallback);saveLoginMethod(fallback)}catch(e){setMessage(String(e))}finally{setBusy(false)}};
 return <section className={styles.card} aria-label="Настройка способа входа"><header><ShieldCheck/><div><h3>Ваш способ входа</h3><p>При запуске показывается только выбранный способ.</p></div></header><label>Способ входа<select aria-label="Основной способ входа" disabled={busy} value={method} onChange={e=>choose(e.target.value as LoginMethod)}><option value="password">Логин и пароль</option><option value="pin">PIN-код</option><option value="hello">Отпечаток · Windows Hello</option></select></label>
  {method==='password'&&<div className={styles.method}><p>Логин: <b>{user.id}</b></p><button onClick={()=>onConfigure('password')}>Настроить пароль</button></div>}
  {method==='pin'&&<div className={styles.method}><p>{user.pinEnabled?'PIN-код настроен. Для входа достаточно шести цифр.':'Задайте PIN-код из шести цифр, чтобы включить этот способ.'}</p><button onClick={()=>onConfigure('pin')}>{user.pinEnabled?'Изменить PIN':'Задать PIN'}</button></div>}
  {method==='hello'&&<div className={styles.method}><p role="status">{hello?.detail||'Проверяем Windows Hello…'}</p><small>Отпечаток проверяет Windows. Сначала настройте его в параметрах входа Windows 11.</small><button disabled={busy||!hello?.available} className="primary" onClick={()=>void(hello?.enrolled?disconnect():connect())}>{busy?<LoaderCircle className="spin"/>:<Fingerprint/>}{busy?'Ожидаем Windows Hello…':hello?.enrolled?'Отключить Windows Hello':'Включить Windows Hello'}</button></div>}
  {message&&<p className={styles.message} role="status">{message.replace(/^Error:\s*/,'')}</p>}
 </section>
}

