  <div className={styles.heading}><span className={styles.icon}><Lightbulb/></span><div><b>Подсветка</b><span>{!online?'Нет связи с принтером':busy?'Переключение…':known?light.on?'Включена':'Выключена':discovering?'Проверяем доступность…':light?.supported?'Состояние не передаётся':'Управление недоступно'}</span></div>
