fn audit_add(
    app: AppHandle,
    auth: State<'_, AuthState>,
    session_token: String,
    action: String,
    details: String,
) -> Result<(), String> {
    let user = require_role(&app, &auth, &session_token, Role::Viewer)?;
    if parse_role(&user.role)? < Role::Operator && !notification_action_allowed(&action) {
        return Err(
            "FORBIDDEN: наблюдатель может записывать только безопасные события уведомлений".into(),
        );
    }
    insert_audit(&app, &user.id, &action, &details)
}

fn notification_action_allowed(action: &str) -> bool {
    matches!(
        action,
        "print.complete"
            | "print.cancelled"
            | "printer.error"
            | "printer.offline"
            | "printer.online"
            | "filament.runout"
            | "print.dispatch"
            | "print.validated_start"
            | "print.queue_add"
            | "queue.auto_start"
            | "queue.manual_start"
            | "queue.auto_blocked"
            | "queue.start_blocked"
            | "gcode.blocked"
            | "schedule.blocked"
            | "maintenance.complete"
            | "maintenance.due"
            | "camera.warning"
            | "camera.paused"
            | "camera.pause_failed"
            | "diagnostics.complete"
            | "history.snapshot_saved"
            | "notification.test"
            | "update.available"
            | "update.current"
            | "update.error"
    )
}

