    .map_err(|error| format!("Local library import finish worker failed: {error}"))??;
    insert_audit(
        &app,
        &user.id,
        "local_library.import_stream",
        &format!(
            "{} · {} · {} bytes · {}",
            printer_id, result.path, result.size, result.status
        ),
    )?;
