//! Desktop Windows Hello. Only the OS Verified result permits authentication.
//! Biometrics never enter the application; the dialog belongs to its HWND.
#[cfg(windows)]
mod platform {
    use std::{thread, time::{Duration, Instant}};
    use windows::{core::{factory, HSTRING, RuntimeType}, Security::Credentials::UI::{UserConsentVerifier, UserConsentVerifierAvailability, UserConsentVerificationResult}, Win32::{Foundation::HWND, System::WinRT::{IUserConsentVerifierInterop, RoInitialize, RoUninitialize, RO_INIT_MULTITHREADED}}};
    use windows_future::{AsyncStatus, IAsyncOperation};

    struct Apartment(bool);
    impl Apartment {
        fn new() -> Result<Self, String> {
            let result=unsafe { RoInitialize(RO_INIT_MULTITHREADED) };
            match result {
                Ok(()) => Ok(Self(true)),
                Err(error) if error.code().0 == 0x80010106u32 as i32 => Ok(Self(false)),
                Err(_) => Err("Windows Hello не удалось запустить".into()),
            }
        }
    }
    impl Drop for Apartment { fn drop(&mut self) { if self.0 { unsafe { RoUninitialize() }; } } }

    fn wait<T:RuntimeType+'static>(op:IAsyncOperation<T>, limit:Duration) -> Result<T,String> {
        let started=Instant::now();
        loop {
            let status=op.Status().map_err(|_|"Windows Hello не ответил".to_string())?;
            if status != AsyncStatus::Started { return op.GetResults().map_err(|_|"Проверка Windows Hello отменена или недоступна".into()); }
            if started.elapsed()>=limit { let _=op.Cancel(); return Err("Время ожидания Windows Hello истекло".into()); }
            thread::sleep(Duration::from_millis(50));
        }
    }
    pub fn available() -> Result<bool,String> {
        let _apartment=Apartment::new()?;
        let op=UserConsentVerifier::CheckAvailabilityAsync().map_err(|_|"Windows Hello недоступен".to_string())?;
        Ok(wait(op,Duration::from_secs(5))? == UserConsentVerifierAvailability::Available)
    }
    pub fn verify(hwnd:isize,message:&str) -> Result<(),String> {
        if hwnd==0 { return Err("Окно программы недоступно".into()); }
        let _apartment=Apartment::new()?;
        let factory:IUserConsentVerifierInterop=factory::<UserConsentVerifier,IUserConsentVerifierInterop>().map_err(|_|"Требуется Windows 11 с настроенным Windows Hello".to_string())?;
        let op:IAsyncOperation<UserConsentVerificationResult>=unsafe { factory.RequestVerificationForWindowAsync(HWND(hwnd as *mut _), &HSTRING::from(message)) }.map_err(|_|"Не удалось открыть Windows Hello".to_string())?;
        let result=wait(op,Duration::from_secs(120))?;
        if result==UserConsentVerificationResult::Verified { Ok(()) } else { Err("Windows Hello не подтвердил вход. Повторите или выберите другой способ".into()) }
    }
}
#[cfg(windows)]
pub use platform::{available,verify};
#[cfg(not(windows))]
pub fn available()->Result<bool,String>{Ok(false)}
#[cfg(not(windows))]
pub fn verify(_hwnd:isize,_message:&str)->Result<(),String>{Err("Windows Hello доступен только в Windows 11".into())}

